// Deterministic, explainable inventory math. The AI step never changes these numbers.
const cfg = $('Config').first().json;
const num = (v) => {
  if (v === null || v === undefined || v === '' || typeof v === 'boolean') return null;
  const n = typeof v === 'number' ? v : Number(String(v).replace(/,/g, '').trim());
  return Number.isFinite(n) ? n : null;
};
const r2 = (n) => Math.round(n * 100) / 100;
const tz = cfg.timezone || 'Asia/Jerusalem';
const historyDays = num(cfg.history_days) || 90;
const defaultLead = num(cfg.default_lead_time_days) ?? 7;
const safetyDays = num(cfg.safety_stock_days) ?? 3;
const w7 = Math.min(1, Math.max(0, num(cfg.demand_weight_7d) ?? 0.5));
const trendPct = num(cfg.trend_change_threshold_pct) ?? 25;
const highMult = num(cfg.high_risk_cover_vs_lead_multiplier) ?? 1;
const mediumExtra = num(cfg.medium_risk_extra_days) ?? 7;
const overstockDays = num(cfg.overstock_days_of_stock) ?? 120;
const levels = ['high', 'medium', 'low'];
const overstockLevel = levels.includes(cfg.overstock_risk_level) ? cfg.overstock_risk_level : 'medium';
const zeroDemandLevel = levels.includes(cfg.zero_demand_with_stock_risk_level) ? cfg.zero_demand_with_stock_risk_level : 'medium';

const nowTz = DateTime.now().setZone(tz);
const today = nowTz.startOf('day');
const runId = String($execution.id) + '-' + nowTz.toFormat('yyyyLLdd-HHmm');
const skips = [];
const skip = (source, sku, ref, reason) => skips.push({ json: { kind: 'skip', run_id: runId, source_table: source, sku: String(sku || ''), row_ref: String(ref), reason } });
const isReal = (i) => i && i.json && Object.keys(i.json).length > 0;

const invItems = $('Get Inventory').all().filter(isReal);
const salesItems = $('Get Sales History').all().filter(isReal);

// 1) Validate inventory rows (active products only, one row per sku)
const products = new Map();
invItems.forEach((it, idx) => {
  const r = it.json;
  const ref = r.id !== undefined ? 'row id ' + r.id : 'index ' + idx;
  const active = r.active === true || String(r.active).toLowerCase() === 'true';
  if (!active) return; // inactive products are out of scope by design
  const sku = String(r.sku ?? '').trim();
  if (!sku) return skip('inventory', '', ref, 'missing sku');
  if (products.has(sku)) return skip('inventory', sku, ref, 'duplicate sku in inventory; only the first row is used');
  const stock = num(r.current_stock);
  if (stock === null) return skip('inventory', sku, ref, 'current_stock is missing or not a number');
  if (stock < 0) return skip('inventory', sku, ref, 'current_stock is negative (' + stock + ')');
  const target = num(r.target_stock);
  if (target === null || target < 0) return skip('inventory', sku, ref, 'target_stock is missing, not a number or negative');
  const notes = [];
  let lead = num(r.lead_time_days);
  let leadSource = 'inventory';
  if (lead === null || lead <= 0) {
    notes.push('lead_time_days missing or invalid in inventory (' + JSON.stringify(r.lead_time_days ?? null) + '); used declared default ' + defaultLead + ' days');
    lead = defaultLead;
    leadSource = 'config_default';
  }
  const sheetRopRaw = r.reorder_point;
  const sheetRop = num(sheetRopRaw);
  const hasSheetRop = sheetRop !== null && sheetRop >= 0;
  if (sheetRopRaw !== null && sheetRopRaw !== undefined && sheetRopRaw !== '' && !hasSheetRop) notes.push('reorder_point in inventory is invalid and was ignored');
  const unitCost = num(r.unit_cost);
  if (unitCost === null || unitCost < 0) notes.push('unit_cost missing or invalid; order cost not estimated');
  products.set(sku, {
    sku,
    product_name: String(r.product_name || '').trim() || sku,
    supplier: String(r.supplier || '').trim(),
    unit_cost: unitCost !== null && unitCost >= 0 ? unitCost : null,
    current_stock: stock,
    target_stock: target,
    sheet_reorder_point: hasSheetRop ? sheetRop : null,
    lead_time_days: lead,
    lead_time_source: leadSource,
    notes,
    byAge: {},
    oldestAge: 0,
    salesRows: 0,
    todayQty: 0,
  });
});

if (products.size === 0) {
  return [{ json: { kind: 'fatal', run_id: runId, message: 'No valid active products in inventory (' + invItems.length + ' rows read, ' + skips.length + ' rejected). No recommendations were produced.' } }].concat(skips);
}

// 2) Validate sales rows and bucket them by days-ago (in the configured timezone)
const unknownSkus = {};
salesItems.forEach((it, idx) => {
  const r = it.json;
  const ref = r.id !== undefined ? 'row id ' + r.id : 'index ' + idx;
  const sku = String(r.sku ?? '').trim();
  if (!sku) return skip('sales_history', '', ref, 'missing sku');
  const qty = num(r.quantity_sold);
  if (qty === null) return skip('sales_history', sku, ref, 'quantity_sold is missing or not a number');
  if (qty < 0) return skip('sales_history', sku, ref, 'quantity_sold is negative (' + qty + ')');
  if (r.sale_date === null || r.sale_date === undefined || r.sale_date === '') return skip('sales_history', sku, ref, 'sale_date is missing');
  const js = new Date(r.sale_date);
  if (isNaN(js.getTime())) return skip('sales_history', sku, ref, 'sale_date is not a valid date (' + String(r.sale_date) + ')');
  const day = DateTime.fromJSDate(js).setZone(tz).startOf('day');
  const age = Math.round(today.diff(day, 'days').days);
  if (age < 0) return skip('sales_history', sku, ref, 'sale_date is in the future (' + day.toISODate() + ')');
  if (age > historyDays) return; // outside the analysis window
  const p = products.get(sku);
  if (!p) { unknownSkus[sku] = (unknownSkus[sku] || 0) + 1; return; }
  if (age === 0) { p.todayQty += qty; return; } // today is incomplete; excluded from averages
  p.byAge[age] = (p.byAge[age] || 0) + qty;
  p.oldestAge = Math.max(p.oldestAge, age);
  p.salesRows += 1;
});
Object.keys(unknownSkus).forEach((sku) => skip('sales_history', sku, unknownSkus[sku] + ' row(s)', 'sku not found among valid active inventory products; sales ignored'));

// 3) Forecast, reorder point, order quantity and risk per product
const sumAges = (byAge, from, to) => { let s = 0; for (let a = from; a <= to; a++) s += byAge[a] || 0; return s; };
const results = [];
products.forEach((p) => {
  const sum7 = sumAges(p.byAge, 1, 7);
  const sum30 = sumAges(p.byAge, 1, 30);
  const sumHist = sumAges(p.byAge, 1, historyDays);
  const avg7 = sum7 / 7;
  const avg30 = sum30 / 30;
  const avgHist = sumHist / historyDays;
  const avg = w7 * avg7 + (1 - w7) * avg30;
  const notes = p.notes.slice();

  if (p.salesRows === 0) notes.push('No valid sales records in the last ' + historyDays + ' days: demand treated as 0 (not estimated)');
  else if (sum30 === 0) notes.push('No sales in the last 30 days (older sales exist, ' + historyDays + '-day avg ' + r2(avgHist) + '/day shown for context only)');
  else if (p.oldestAge < 30) notes.push('Sales history covers only ' + p.oldestAge + ' day(s); the 30-day average may understate demand');
  if (p.todayQty > 0) notes.push('Today\'s partial sales (' + p.todayQty + ') excluded from averages');

  let trend = 'stable';
  let trendChange = null;
  if (avg7 === 0 && avg30 === 0) trend = 'no_demand';
  else if (avg30 === 0) trend = 'rising';
  else {
    trendChange = (avg7 / avg30 - 1) * 100;
    if (trendChange >= trendPct) trend = 'rising';
    else if (trendChange <= -trendPct) trend = 'falling';
  }

  const forecast7 = avg * 7;
  const daysOfStock = avg > 0 ? p.current_stock / avg : null; // null = no demand, stock never runs out at current rate
  const leadDemand = avg * p.lead_time_days;
  const safetyUnits = avg * safetyDays;
  const computedRop = leadDemand + safetyUnits;
  const effectiveRop = Math.max(computedRop, p.sheet_reorder_point ?? 0);
  const needsReorder = avg > 0 && p.current_stock <= effectiveRop;
  const projectedAtArrival = Math.max(0, p.current_stock - leadDemand);
  const qty = needsReorder ? Math.max(0, Math.ceil(p.target_stock - projectedAtArrival)) : 0;
  if (avg === 0 && p.current_stock <= (p.sheet_reorder_point ?? -1)) notes.push('Stock is at/below the manual reorder_point but there is no recorded demand, so no quantity is suggested');

  let level = 'low';
  let type = 'none';
  let rule = 'No rule triggered';
  if (avg > 0) {
    if (p.current_stock <= 0 || daysOfStock <= p.lead_time_days * highMult) {
      level = 'high'; type = 'stockout';
      rule = 'days_of_stock (' + r2(daysOfStock) + ') <= lead_time_days x ' + highMult + ' (' + r2(p.lead_time_days * highMult) + ')';
    } else if (p.current_stock <= effectiveRop || daysOfStock <= p.lead_time_days + safetyDays + mediumExtra) {
      level = 'medium'; type = 'stockout';
      rule = 'current_stock (' + p.current_stock + ') <= reorder point (' + r2(effectiveRop) + ') or days_of_stock (' + r2(daysOfStock) + ') <= lead + safety + ' + mediumExtra + ' days (' + (p.lead_time_days + safetyDays + mediumExtra) + ')';
    } else if (daysOfStock >= overstockDays) {
      level = overstockLevel; type = 'overstock';
      rule = 'days_of_stock (' + r2(daysOfStock) + ') >= overstock threshold (' + overstockDays + ')';
    }
  } else if (p.current_stock > 0) {
    level = zeroDemandLevel; type = 'no_demand_overstock';
    rule = 'zero demand with stock on hand (' + p.current_stock + ' units)';
  } else {
    type = 'no_demand';
    rule = 'zero demand and zero stock';
  }

  const calc = [
    'avg_7d=' + r2(sum7) + '/7=' + r2(avg7),
    'avg_30d=' + r2(sum30) + '/30=' + r2(avg30),
    'avg_daily_demand=' + w7 + 'xavg_7d+' + r2(1 - w7) + 'xavg_30d=' + r2(avg),
    'trend=' + trend + (trendChange === null ? '' : ' (' + r2(trendChange) + '%)'),
    'forecast_7d=' + r2(forecast7),
    'days_of_stock=' + (daysOfStock === null ? 'n/a (zero demand)' : p.current_stock + '/' + r2(avg) + '=' + r2(daysOfStock)),
    'reorder_point=' + r2(avg) + 'x' + p.lead_time_days + 'd lead + ' + r2(avg) + 'x' + safetyDays + 'd safety=' + r2(computedRop) + (p.sheet_reorder_point !== null ? ' (manual ' + p.sheet_reorder_point + ', effective ' + r2(effectiveRop) + ')' : ''),
    'suggested_order_qty=' + (needsReorder ? 'ceil(target ' + p.target_stock + ' - projected stock at arrival ' + r2(projectedAtArrival) + ')=' + qty : '0 (stock above reorder point or no demand)'),
    'risk=' + level + ': ' + rule,
  ].join('; ');

  results.push({
    json: {
      kind: 'product',
      run_id: runId,
      sku: p.sku,
      product_name: p.product_name,
      supplier: p.supplier,
      currency: cfg.currency || 'ILS',
      unit_cost: p.unit_cost,
      current_stock: p.current_stock,
      target_stock: p.target_stock,
      manual_reorder_point: p.sheet_reorder_point,
      lead_time_days: p.lead_time_days,
      lead_time_source: p.lead_time_source,
      safety_stock_days: safetyDays,
      sales_rows_used: p.salesRows,
      avg_7d: r2(avg7),
      avg_30d: r2(avg30),
      avg_daily_demand: r2(avg),
      trend_change_pct: trendChange === null ? null : r2(trendChange),
      demand_trend: trend,
      forecast_7d: r2(forecast7),
      days_of_stock: daysOfStock === null ? null : r2(daysOfStock),
      lead_time_demand: r2(leadDemand),
      safety_stock_units: r2(safetyUnits),
      computed_reorder_point: r2(computedRop),
      effective_reorder_point: r2(effectiveRop),
      needs_reorder: needsReorder,
      suggested_order_qty: qty,
      estimated_order_cost: p.unit_cost !== null ? r2(qty * p.unit_cost) : null,
      risk_level: level,
      risk_type: type,
      risk_rule: rule,
      data_notes: notes,
      calc_explanation: calc,
    },
  });
});

const rank = { high: 0, medium: 1, low: 2 };
results.sort((a, b) => rank[a.json.risk_level] - rank[b.json.risk_level] || (a.json.days_of_stock ?? 1e9) - (b.json.days_of_stock ?? 1e9));
return results.concat(skips);

