// Numbers always come from Compute Forecast. AI text is attached only as explanation.
const f = $('Route Results').item.json;
let ai = ($json && $json.output && typeof $json.output === 'object') ? $json.output : null;
const NL = String.fromCharCode(10);
const parts = ['[Calculation] ' + f.calc_explanation];
if (f.data_notes && f.data_notes.length) parts.push('[Data notes] ' + f.data_notes.join(' | '));
// Guard: discard AI text that mentions any number not present in the calculated facts
if (ai) {
  const numRe = /\d+(?:\.\d+)?/g;
  const allowed = new Set((JSON.stringify(f).match(numRe) || []).map((n) => String(Number(n))));
  const aiNums = (JSON.stringify(ai).match(numRe) || []).map((n) => String(Number(n)));
  const foreign = aiNums.filter((n) => !allowed.has(n));
  if (foreign.length) {
    parts.push('[AI guard] AI explanation discarded: it contained numbers not in the calculated facts (' + Array.from(new Set(foreign)).slice(0, 5).join(', ') + ')');
    ai = null;
  }
}
if (ai) {
  parts.push('[AI explanation] ' + String(ai.risk_summary || ''));
  if (Array.isArray(ai.drivers) && ai.drivers.length) parts.push('[Drivers] ' + ai.drivers.join(' | '));
  if (Array.isArray(ai.scenarios) && ai.scenarios.length) parts.push('[Scenarios] ' + ai.scenarios.map((s) => String(s.name || '') + ': ' + String(s.description || '')).join(' | '));
  if (ai.review_note) parts.push('[Review] ' + ai.review_note);
  if (ai.data_caveats) parts.push('[Caveats] ' + ai.data_caveats);
} else {
  parts.push('[AI explanation] unavailable in this run; numbers above are deterministic and unaffected');
}
parts.push('[Approval] status=pending_approval. No purchase order was created and no supplier was contacted.');
return {
  json: {
    run_id: f.run_id,
    sku: f.sku,
    product_name: f.product_name,
    supplier: f.supplier,
    currency: f.currency,
    current_stock: f.current_stock,
    target_stock: f.target_stock,
    lead_time_days: f.lead_time_days,
    lead_time_source: f.lead_time_source,
    avg_7d: f.avg_7d,
    avg_30d: f.avg_30d,
    avg_daily_demand: f.avg_daily_demand,
    demand_trend: f.demand_trend,
    forecast_7d: f.forecast_7d,
    days_of_stock: f.days_of_stock,
    computed_reorder_point: f.computed_reorder_point,
    effective_reorder_point: f.effective_reorder_point,
    suggested_order_qty: f.suggested_order_qty,
    estimated_order_cost: f.estimated_order_cost,
    risk_level: f.risk_level,
    risk_type: f.risk_type,
    risk_rule: f.risk_rule,
    ai_summary: ai ? String(ai.risk_summary || '') : '',
    explanation: parts.join(NL).slice(0, 8000),
    status: 'pending_approval',
    created_at: DateTime.now().toISO(),
  },
};

// One summary per run; each sku appears at most once.
const cfg = $('Config').first().json;
const NL = String.fromCharCode(10);
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const recs = $('Prepare Recommendation').all().map((i) => i.json);
const skipped = $('Compute Forecast').all().filter((i) => i.json.kind === 'skip').length;
const seen = new Set();
const flagged = [];
for (const r of recs) {
  if (r.risk_level !== 'high' && r.risk_level !== 'medium') continue;
  if (seen.has(r.sku)) continue;
  seen.add(r.sku);
  flagged.push(r);
}
const rank = { high: 0, medium: 1 };
flagged.sort((a, b) => rank[a.risk_level] - rank[b.risk_level] || (a.days_of_stock ?? 1e9) - (b.days_of_stock ?? 1e9));
const runId = recs.length ? recs[0].run_id : '';
const header = '<b>Inventory Control Tower</b> - ' + esc(DateTime.now().setZone(cfg.timezone).toFormat('yyyy-LL-dd HH:mm')) + NL
  + 'Products analysed: ' + recs.length + ' | High: ' + flagged.filter((r) => r.risk_level === 'high').length + ' | Medium: ' + flagged.filter((r) => r.risk_level === 'medium').length + ' | Skipped rows: ' + skipped + NL
  + 'All recommendations are <b>pending_approval</b>. No purchase order was created and no supplier was contacted.';
const blocks = flagged.map((r) => [
  (r.risk_level === 'high' ? '<b>[HIGH]</b> ' : '<b>[MEDIUM]</b> ') + esc(r.product_name) + ' (' + esc(r.sku) + ') - ' + esc(r.risk_type),
  'Stock: ' + r.current_stock + ' | Avg/day: ' + r.avg_daily_demand + ' (7d ' + r.avg_7d + ', 30d ' + r.avg_30d + ', ' + esc(r.demand_trend) + ')',
  'Forecast 7d: ' + r.forecast_7d + ' | Days of stock: ' + (r.days_of_stock === null ? 'n/a (zero demand)' : r.days_of_stock),
  'Lead time: ' + r.lead_time_days + 'd' + (r.lead_time_source === 'config_default' ? ' (default)' : '') + ' | Reorder point: ' + r.effective_reorder_point,
  'Suggested qty: <b>' + r.suggested_order_qty + '</b>' + (r.estimated_order_cost !== null && r.suggested_order_qty > 0 ? ' (~' + r.estimated_order_cost + ' ' + esc(r.currency) + ')' : ''),
  'Rule: ' + esc(r.risk_rule),
  r.ai_summary ? 'Why: ' + esc(r.ai_summary).slice(0, 400) : '',
].filter(Boolean).join(NL));
if (blocks.length === 0) blocks.push('No high or medium risk products today.');
const messages = [];
let current = header;
for (const b of blocks) {
  if ((current + NL + NL + b).length > 3800) { messages.push(current); current = b; }
  else current = current + NL + NL + b;
}
messages.push(current + NL + NL + 'Run: ' + esc(runId));
return messages.map((text) => ({ json: { text } }));
